// Command covergate enforces the statement coverage gate on a Go cover
// profile and writes coverage/summary.json in the shared sdk-kit format:
//
//	{"lines": {"covered": N, "total": N, "pct": X}, "branches": null}
//
// Go has no stable branch metric, so "lines" carries statement coverage and
// "branches" is null (decision recorded in GRO-1366). Blocks reported by
// several test binaries (-coverpkg) are merged: a block counts as covered
// when any binary executed it.
package main

import (
	"bufio"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"math"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
)

type block struct {
	stmts   int
	covered bool
}

// summary is the machine-readable coverage summary.
type summary struct {
	Lines    metric  `json:"lines"`
	Branches *metric `json:"branches"`
}

type metric struct {
	Covered int     `json:"covered"`
	Total   int     `json:"total"`
	Pct     float64 `json:"pct"`
}

func main() {
	profile := flag.String("profile", "coverage/coverage.out", "cover profile written by go test -coverprofile")
	minPct := flag.Float64("min", 90, "minimum statement coverage in percent")
	out := flag.String("summary", "coverage/summary.json", "summary JSON output path")
	exclude := flag.String("exclude", "/internal/tools/", "comma-separated path substrings to ignore")
	flag.Parse()
	if err := run(*profile, *out, *minPct, splitList(*exclude), os.Stdout); err != nil {
		fmt.Fprintln(os.Stderr, "covergate:", err)
		os.Exit(1)
	}
}

func splitList(s string) []string {
	var out []string
	for _, p := range strings.Split(s, ",") {
		if p = strings.TrimSpace(p); p != "" {
			out = append(out, p)
		}
	}
	return out
}

func run(profile, out string, minPct float64, exclude []string, w io.Writer) error {
	f, err := os.Open(profile)
	if err != nil {
		return err
	}
	defer f.Close()
	blocks, perFile, err := parse(f, exclude)
	if err != nil {
		return err
	}
	s := summarize(blocks)
	if err := writeSummary(out, s); err != nil {
		return err
	}
	files := make([]string, 0, len(perFile))
	for name := range perFile {
		files = append(files, name)
	}
	sort.Strings(files)
	for _, name := range files {
		m := summarize(perFile[name])
		fmt.Fprintf(w, "%6.2f%%  %4d/%-4d  %s\n", m.Lines.Pct, m.Lines.Covered, m.Lines.Total, name)
	}
	fmt.Fprintf(w, "statements: %d/%d = %.2f%% (gate %.0f%%)\n", s.Lines.Covered, s.Lines.Total, s.Lines.Pct, minPct)
	if float64(s.Lines.Covered)*100 < minPct*float64(s.Lines.Total) {
		return fmt.Errorf("statement coverage %.2f%% is below %.0f%%", s.Lines.Pct, minPct)
	}
	return nil
}

func parse(r io.Reader, exclude []string) (map[string]*block, map[string]map[string]*block, error) {
	blocks := map[string]*block{}
	perFile := map[string]map[string]*block{}
	sc := bufio.NewScanner(r)
	sc.Buffer(make([]byte, 1024*1024), 1024*1024)
	first := true
	for sc.Scan() {
		line := strings.TrimSpace(sc.Text())
		if line == "" {
			continue
		}
		if first {
			first = false
			if strings.HasPrefix(line, "mode:") {
				continue
			}
		}
		if strings.HasPrefix(line, "mode:") {
			continue // concatenated profiles
		}
		// file.go:startLine.startCol,endLine.endCol numStmts count
		fields := strings.Fields(line)
		if len(fields) != 3 {
			return nil, nil, fmt.Errorf("malformed profile line %q", line)
		}
		colon := strings.LastIndex(fields[0], ":")
		if colon < 0 {
			return nil, nil, fmt.Errorf("malformed profile line %q", line)
		}
		file := fields[0][:colon]
		if skip(file, exclude) {
			continue
		}
		stmts, err1 := strconv.Atoi(fields[1])
		count, err2 := strconv.Atoi(fields[2])
		if err := errors.Join(err1, err2); err != nil {
			return nil, nil, fmt.Errorf("malformed profile line %q: %w", line, err)
		}
		b, ok := blocks[fields[0]]
		if !ok {
			b = &block{stmts: stmts}
			blocks[fields[0]] = b
			if perFile[file] == nil {
				perFile[file] = map[string]*block{}
			}
			perFile[file][fields[0]] = b
		}
		if count > 0 {
			b.covered = true
		}
	}
	if err := sc.Err(); err != nil {
		return nil, nil, err
	}
	if len(blocks) == 0 {
		return nil, nil, errors.New("profile has no coverage blocks")
	}
	return blocks, perFile, nil
}

func skip(file string, exclude []string) bool {
	for _, e := range exclude {
		if strings.Contains(file, e) {
			return true
		}
	}
	return false
}

func summarize(blocks map[string]*block) summary {
	var m metric
	for _, b := range blocks {
		m.Total += b.stmts
		if b.covered {
			m.Covered += b.stmts
		}
	}
	if m.Total > 0 {
		m.Pct = math.Round(float64(m.Covered)/float64(m.Total)*10000) / 100
	}
	return summary{Lines: m}
}

func writeSummary(path string, s summary) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	data, err := json.MarshalIndent(s, "", "  ")
	if err != nil {
		return err
	}
	return os.WriteFile(path, append(data, '\n'), 0o600)
}
